package com.franco.desco.domain.sanitation;import java.math.BigDecimal;import java.time.Instant;import java.util.List;
public final class SanitationModels{private SanitationModels(){}public record Summary(Long casoFitosanitarioId,Instant fechaDeteccion,String estadoCaso,String severidad,Integer plantasAfectadas,boolean cantidadEstimada,String codigoProblema,String problema,Long parcelaCultivoId,Long parcelaId,String parcelaNombre,Long predioId,String predioCodigo,String predioNombre,Long socioId,String numeroDocumento,String socioNombre,Long evidencias){}public record Header(Long casoFitosanitarioId,Long parcelaCultivoId,Integer tipoProblemaId,String codigoProblema,String categoria,String problema,Long visitaDeteccionId,Instant fechaDeteccion,Integer plantasAfectadas,boolean cantidadEstimada,String severidad,String estadoCaso,String observacion,Long parcelaId,String parcelaNombre,Long predioId,String predioCodigo,String predioNombre,String variedad){}public record Treatment(Long tratamientoId,Instant fechaHora,Long visitaTecnicaId,Long responsableEmpleadoId,String responsable,String tratamiento,String producto,BigDecimal dosis,String unidadDosis,String observacion,Long programacionProductoId,BigDecimal cantidadUtilizada,String unidadUtilizada){}public record FollowUp(Long seguimientoId,Instant fechaHora,Long visitaTecnicaId,Integer plantasAfectadas,boolean cantidadEstimada,String severidad,String resultado,String observacion){}public record File(Long archivoId,String nombreOriginal,String mimeType,String secureUrl,String categoria,String origenCaptura,String descripcion,Instant fechaCarga,Instant fechaCaptura){}public record Detail(Header caso,List<Treatment>tratamientos,List<FollowUp>seguimientos,List<File>archivos){public Detail{tratamientos=tratamientos==null?List.of():List.copyOf(tratamientos);seguimientos=seguimientos==null?List.of():List.copyOf(seguimientos);archivos=archivos==null?List.of():List.copyOf(archivos);}}}
